from collections import defaultdict

class Solution:
    def isCircle(self, N: int, A: list) -> int:
        if N == 0:
            return 0

        in_degree = defaultdict(int)
        out_degree = defaultdict(int)

        for s in A:
            first_char = s[0]
            last_char = s[-1]
            out_degree[first_char] += 1
            in_degree[last_char] += 1

        all_chars = set(in_degree.keys()) | set(out_degree.keys())

        for char in all_chars:
            if in_degree[char] != out_degree[char]:
                return 0

        adj = defaultdict(list)
        for s in A:
            first_char = s[0] 
            last_char = s[-1]
            adj[first_char].append(last_char)

        start_node = A[0][0]
        visited_count = 0
        stack = [start_node]
        path = []

        while stack:
            node = stack[-1]
            if adj[node]:
                next_node = adj[node].pop()
                stack.append(next_node)
            else:
                path.append(stack.pop())
                visited_count += 1

        if visited_count != N:
            return 0

        if path[0] != start_node:
            return 0

        return 1
